        private static readonly HashSet<string> DefaultItemIds = new(ById.Keys, StringComparer.OrdinalIgnoreCase);

        public static int Count => ById.Count;

        public static IEnumerable<HeroDefaultItemInfo> AllItems => ById.Values;

        public static bool TryGetItem(string? itemId, out HeroDefaultItemInfo info)
        {
            if (!string.IsNullOrWhiteSpace(itemId) && ById.TryGetValue(itemId.Trim(), out var item))
            {
                info = item;
                return true;
            }

            info = null!;
            return false;
        }

        public static bool TryGetItem(int itemId, out HeroDefaultItemInfo info)
        {
            return TryGetItem(itemId.ToString(CultureInfo.InvariantCulture), out info);
        }

        public static bool IsHeroDefaultItem(string? itemId)
        {
            return !string.IsNullOrWhiteSpace(itemId) && DefaultItemIds.Contains(itemId.Trim());
        }

        public static bool IsHeroDefaultItem(int itemId)
        {
            return IsHeroDefaultItem(itemId.ToString(CultureInfo.InvariantCulture));
        }

        public static string FormatHeroName(string? heroId)
        {
            if (string.IsNullOrWhiteSpace(heroId))
                return "Universal";

            var clean = heroId.Trim().ToLowerInvariant();
            switch (clean)
            {
                case "npc_dota_hero_antimage": return "Anti-Mage";
                case "npc_dota_hero_nevermore": return "Shadow Fiend";
                case "npc_dota_hero_zuus": return "Zeus";
                case "npc_dota_hero_furion": return "Nature's Prophet";
