                case "npc_dota_hero_phantom_assassin": return "Phantom Assassin";
                case "npc_dota_hero_phantom_lancer": return "Phantom Lancer";
                case "npc_dota_hero_spirit_breaker": return "Spirit Breaker";
                case "npc_dota_hero_storm_spirit": return "Storm Spirit";
