                case "npc_dota_hero_sand_king": return "Sand King";
                case "npc_dota_hero_shadow_demon": return "Shadow Demon";
                case "npc_dota_hero_skywrath_mage": return "Skywrath Mage";
                case "npc_dota_hero_ogre_magi": return "Ogre Magi";
                case "npc_dota_hero_naga_siren": return "Naga Siren";
                case "npc_dota_hero_dark_willow": return "Dark Willow";
                case "npc_dota_hero_dark_seer": return "Dark Seer";
                case "npc_dota_hero_elder_titan": return "Elder Titan";
                case "npc_dota_hero_faceless_void": return "Faceless Void";
                case "npc_dota_hero_night_stalker": return "Night Stalker";
                case "npc_dota_hero_nyx_assassin": return "Nyx Assassin";
                case "npc_dota_hero_bounty_hunter": return "Bounty Hunter";
                case "npc_dota_hero_chaos_knight": return "Chaos Knight";
                case "npc_dota_hero_ancient_apparition": return "Ancient Apparition";
                case "npc_dota_hero_arc_warden": return "Arc Warden";
                case "npc_dota_hero_dragon_knight": return "Dragon Knight";
                case "all": return "All Heroes";
                default:
                    var name = clean;
                    if (name.StartsWith("npc_dota_hero_", StringComparison.OrdinalIgnoreCase))
                        name = name.Substring(14);
                    else if (name.StartsWith("npc_dota_", StringComparison.OrdinalIgnoreCase))
                        name = name.Substring(9);
                    else if (name.StartsWith("dota_", StringComparison.OrdinalIgnoreCase))
                        name = name.Substring(5);

                    return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(name.Replace("_", " "));
            }
        }

        public static string FormatSlotDisplayName(string? slot, string? itemName = null)
        {
            if (string.IsNullOrWhiteSpace(slot))
            {
                if (!string.IsNullOrWhiteSpace(itemName))
                {
                    var lower = itemName.ToLowerInvariant();
                    if (lower.Contains("weapon") || lower.Contains("sword") || lower.Contains("axe") ||
                        lower.Contains("glaive") || lower.Contains("bow") || lower.Contains("staff") ||
                        lower.Contains("blade") || lower.Contains("spear") || lower.Contains("hook") ||
                        lower.Contains("hammer") || lower.Contains("mace") || lower.Contains("dagger") ||
                        lower.Contains("gun") || lower.Contains("crossbow") || lower.Contains("sickle") ||
                        lower.Contains("wand") || lower.Contains("totem") || lower.Contains("anchor"))
                    {
                        return "Weapon";
                    }
                }
                return "Default";
            }

            var clean = slot.Trim().ToLowerInvariant();
            switch (clean)
            {
                case "ability_effects_1": return "Ability Effects 1";
                case "ability_effects_2": return "Ability Effects 2";
                case "ability_effects_3": return "Ability Effects 3";
                case "ability_effects_4": return "Ability Effects 4";
                case "hero_base": return "Base Model";
                case "base": return "Base Model";
                case "body_head": return "Body / Head";
                case "offhand_weapon": return "Off-Hand Weapon";
                case "ambient_effects": return "Ambient Effects";
                case "summon": return "Summon / Unit";
                case "weapon": return "Weapon";
                case "head": return "Head";
                case "armor": return "Armor";
                case "back": return "Back";
                case "shoulder": return "Shoulder";
                case "arms": return "Arms";
                case "legs": return "Legs";
                case "belt": return "Belt";
                case "neck": return "Neck";
                case "gloves": return "Gloves";
                case "misc": return "Misc";
                case "tail": return "Tail";
                case "wings": return "Wings";
                case "mount": return "Mount";
                default:
                    return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(clean.Replace("_", " "));
            }
        }
    }
